# SemVer 2.0.0 resmi deseni
SEMVER_REGEX = r'^(v)?(?P<major>0|[1-9]\d*)\.(?P<minor>0|[1-9]\d*)\.(?P<patch>0|[1-9]\d*)(?:-(?P<prerelease>(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+(?P<build>[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'


def compare(a: str, b: str) -> int:
    """Semantic Versioning 2.0.0 karşılaştırması.

    a < b ise -1, eşitse 0, a > b ise 1 döner.
    Geçersiz sürüm metni ValueError fırlatır.
    """
    match_a = re.match(SEMVER_REGEX, a)
    if not match_a:
        raise ValueError(f"Geçersiz sürüm metni: {a}")

    match_b = re.match(SEMVER_REGEX, b)
    if not match_b:
        raise ValueError(f"Geçersiz sürüm metni: {b}")

    # Grupları çıkar
    def extract_parts(match):
        major = int(match.group('major'))
        minor = int(match.group('minor'))
        patch = int(match.group('patch'))
        prerelease = match.group('prerelease') or ''

        return major, minor, patch, prerelease

    a_major, a_minor, a_patch, a_prerelease = extract_parts(match_a)
    b_major, b_minor, b_patch, b_prerelease = extract_parts(match_b)

    # MAJOR, MINOR, PATCH karşılaştırması
    if a_major != b_major:
        return -1 if a_major < b_major else 1
    if a_minor != b_minor:
        return -1 if a_minor < b_minor else 1
    if a_patch != b_patch:
        return -1 if a_patch < b_patch else 1

    # PRERELEASE karşılaştırması (yoksa boş string)
    def compare_prerelease(pre_a: str, pre_b: str) -> int:
        if not pre_a and not pre_b:
            return 0

        if not pre_a:
            # a'da yok, b'de var => a < b
            return -1

        if not pre_b:
            # b'de yok, a'da var => a > b
            return 1

        # Her iki prerelease de varsa parçalara ayır
        parts_a = pre_a.split('.')
        parts_b = pre_b.split('.')

        for i in range(max(len(parts_a), len(parts_b))):
            if i >= len(parts_a):
                return -1  # a daha kısa => a < b
            if i >= len(parts_b):
                return 1   # b daha kısa => a > b

            id_a = parts_a[i]
            id_b = parts_b[i]

            # Her iki parça da sayısal ise sayısal karşılaştırma
            try:
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a != num_b:
                    return -1 if num_a < num_b else 1
            except ValueError:
                # En az biri alfanümerik ise alfabetik karşılaştırma (küçükten büyüğe)
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1

        return 0

    prerelease_result = compare_prerelease(a_prerelease, b_prerelease)
    if prerelease_result != 0:
        return prerelease_result

    # BUILD bilgisi önceliği etkilemez, eşitse 0 döner
    return 0


def sort_versions(versions: list[str]) -> list[str]:
    """Sürümleri SemVer kurallarına göre artan sırala.

    Eşit öncelikli sürümler girdideki sıralarını korur (stabilite).
    Geçersiz bir sürüm ValueError fırlatır.
    """
    def version_key(version: str):
        match = re.match(SEMVER_REGEX, version)
        if not match:
            raise ValueError(f"Geçersiz sürüm metni: {version}")

        major = int(match.group('major'))
        minor = int(match.group('minor'))
        patch = int(match.group('patch'))
        prerelease = match.group('prerelease') or ''

        # Prerelease için karşılaştırma anahtarı oluştur
        def prerelease_key(pre: str):
            if not pre:
                return (1, [])  # Prereless olmayanlar sona gider
            parts = pre.split('.')
            keys = []
            for part in parts:
                try:
                    keys.append((0, int(part)))  # Sayısal parçalar önce
                except ValueError:
                    keys.append((1, part))      # Alfabetik parçalar sonra
            return (0, keys)  # Prereless olanlar başa gider

        prerelease_key_val = prerelease_key(prerelease)

        return (major, minor, patch, prerelease_key_val)

    # Anahtarlı sıralama ile stabilize sıralama yap
    sorted_versions = sorted(versions, key=version_key)

    return sorted_versions
